package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamVannamBank2 {
    private const val T = "උඩරට දහඅට වන්නම්, ශාස්ත්‍රීය කවි හා තාල විග්‍රහය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("දහඅට වන්නම්වලින් 'සත්ව' නොවන එහෙත් 'මිනිස් ගුණ හා රාජ තේජස' වර්ණනා කරන ප්‍රධාන වන්නම කුමක්ද?", "උදාර වන්නම", "ගජගා වන්නම", "තුරඟා වන්නම", "උකුසා වන්නම", "උදාර වන්නම රජතුමාගේ තේජස, සිව්රඟ සෙනඟ හා ගෞරවය වර්ණනා කරයි."),
        q("වෛරෝඩි වන්නමේ තේමාව තුළ සඳහන් වන දිව්‍යමය මැණිකෙහි හෝ ලෝකයේ වර්ණනාව අයත් වන්නේ කුමන කාණ්ඩයටද?", "දේව හා ස්වභාව වර්ණනා කාණ්ඩයට", "ගොවි ජන ක්‍රීඩා කාණ්ඩයට", "පහතරට සන්නි කාණ්ඩයට", "සොකරි කෝලම් කාණ්ඩයට", "ඊශ්වර දෙවියන් හා දිව්‍යමය විභූතිය වෛරෝඩි වන්නමේ කවිවලින් පැහැදිලි වේ."),
        q("උඩරට 'වන්නම්' ගායනා කිරීමේදී මූලික තාලය අල්ලා ගැනීමට යොදාගන්නා කුඩා ලෝහ වාද්‍ය භාණ්ඩය කුමක්ද?", "තාලම්පට", "හොරණෑව", "හක්ගෙඩිය", "මද්දලය", "තාලම්පට මඟින් 'තිත්' සහ 'තා' නාද දී ගායකයාට හා නැට්ටුවාට ලය ස්ථිර කරයි."),
        q("ගජගා වන්නමේ 'කවිය' ගයන අවස්ථාවේදී ඇතාගේ හොඬවැල වැනීම පෙන්වීමට භාවිත කරන ශරීර අංගය කුමක්ද?", "දකුණු අත හා බාහුව ඉදිරියට දිගු කර පැද්දීම", "වම් කකුල පසුපසට විසි කිරීම", "හිස බිම තැබීම", "දණහිස් එකට ගැටීම", "අලි ඇතුන්ගේ සොඬයේ චලනය දෑත් මගින් අලංකාරව අනුකරණය කෙරේ."),
        q("මයුරා වන්නමේදී මොනරාගේ 'පිල් විදහා නැටීම' නිරූපණය කිරීම සඳහා නැට්ටුවා භාවිත කරන අත් ඉරියව්ව කුමක්ද?", "දෑත් හිසට ඉහළින් කවාකාරව විහිදා ඇඟිලි සැලීම", "අත් දෙක ඉණට තබා සිටීම", "මිට මොළවා පපුවේ තැබීම", "පිටුපසින් අත් බැඳ ගැනීම", "දෙඅත් මයුර හස්තය හෝ අලපද්ම හස්තය ඇසුරෙන් මොනර පිල් මවයි."),
        q("හනුමා වන්නම නැටීමේදී වඳුරා අතු අතරින් පැනීම දැක්වීමට යොදා ගන්නා ප්‍රධාන නැටුම් පියවර කුමක්ද?", "උස පැනුම් සහ ඉක්මන් හැරී බැලීම්", "මන්දගාමී ඇවිදීම", "නිශ්චලව සිටගෙන සිටීම", "බිම වැතිරී සිටීම", "හනුමාගේ ජවය හා කඩිසර ගමන පැනුම් මගින් නිරූපණය වේ."),
        q("සිංහරාජ වන්නමේ තානම සහ කවිය තුළ පවතින ප්‍රධාන නාද ගුණය කුමක්ද?", "ගාම්භීර හා ශක්තිමත් නාද රටාව", "දුක්මුසු විලාප ස්වරය", "ළමා නැළවිලි ස්වරය", "විකට කතා ස්වරය", "සිංහයාගේ තේජස ගායනයේදී හා ගැටබෙර පදවලදී ගාම්භීර ලෙස ඇසේ."),
        q("උඩරට වන්නම්වල 'සීරුමාරුව' කොටස සඳහා ගැටබෙරයෙන් වාදනය කරන පද පෙළෙහි ස්වභාවය කුමක්ද?", "සමබර හා කෙටි අවධාරණාත්මක බෙර පද මාලාවකි", "විනාඩි දහයක් එක දිගට වැයෙන පදයකි", "බෙර වාදනය නතර කරන විරාමයකි", "වයලීන් වාදනයකි", "කස්තිරම අවසන් කර අඩව්ව සඳහා සිරුර සූදානම් කිරීම සීරුමාරුවෙන් සිදු වේ."),
        q("මුසලඩි වන්නමේ 'මුසල' යන පාලි හෝ සංස්කෘත මූල පදයෙන් අදහස් කරන සත්වයා කවුද?", "හාවා", "මුවා", "මොනරා", "අශ්වයා", "'මුසල' යනු සංස්කෘත හා පාලි බසින් හාවා හැඳින්වීමට යෙදෙන නමකි."),
        q("උඩරට වන්නම් නාමාවලියෙහි 'තුරඟා' යන නාමයෙන් හඳුන්වනු ලබන්නේ කුමන සත්වයාද?", "අශ්වයා", "ඇතා", "උකුස්සා", "සිංහයා", "'තුරඟ' යනු වේගයෙන් ගමන් කරන අශ්වයා සඳහා යෙදෙන පර්යාය පදයකි."),
        q("නෛයඩි වන්නමේ 'නෛයඩි' යන වචනය බිඳී ආ ආකාරය ලෙස සාමාන්‍යයෙන් සලකන්නේ කුමන සංකල්පයක්ද?", "නාගයා හෙවත් නයි ආඩි යන අර්ථය", "මොනරා යන අර්ථය", "සිංහයා යන අර්ථය", "කිරලා යන අර්ථය", "නාග රාජයාගේ රැඟුම හා සිදුහත් කුමරුගේ දුනු ශිල්ප පුවත මෙම වන්නමේ සඳහන් වේ."),
        q("කුදිරඩි හෙවත් ඉරඩි වන්නමේ 'කුදිර' යන දෙමළ හුරු වචනයේ අර්ථය කුමක්ද?", "අශ්වයා හෙවත් අසු පැදීම", "ඇතා", "සර්පයා", "වඳුරා", "යුද සෙබළුන් අසුන් මෙහෙයවීම හා අසුගේ ජවය කුදිරඩි වන්නමෙන් දැක්වේ."),
        q("උඩරට වන්නම්වලදී 'මැදුම් දෙතිත' තාලය තුළ අන්තර්ගත වන මූලික ගණන හෙවත් තිත් ගණන කීයද?", "තිත් දෙකකි (මාත්‍රා 2 බැගින් ආවර්තන)", "තිත් හතරකි (මාත්‍රා 4 බැගින් ආවර්තන)", "තිත් අටකි (මාත්‍රා 8 බැගින් ආවර්තන)", "තිත් දහයකි (මාත්‍රා 10 බැගින් ආවර්තන)", "දෙතිත යනු එක් තාල ආවර්තයකට තිත් දෙකක් වැටෙන සරල රිද්මයයි."),
        q("උඩරට දහඅට වන්නම් අතුරින් 'සුරපති' යන්නෙහි අර්ථය කුමක්ද?", "සුරයන්ට හෙවත් දෙවියන්ට අධිපති ශක්‍ර දෙවියන්", "පක්ෂීන්ට අධිපති ගුරුළා", "වනයට අධිපති සිංහයා", "ජලයට අධිපති වරුණ", "'සුර' යනු දෙවියන් වන අතර 'පති' යනු නායකයා හෙවත් අධිපති යන්නයි."),
        q("ගණපති වන්නම ආරම්භයේදී ශිල්පියා වැඩි ගෞරවයකින් ගායනා කරන්නේ කුමක් නිසාද?", "ගණ දෙවියන් ශාස්ත්‍රයට හා බාධක දුරු කිරීමට අධිපති වන බැවින්", "ගණ දෙවියන් යුද්ධයට අධිපති බැවින්", "ගණ දෙවියන් වන සතුන්ට අධිපති බැවින්", "ගණ දෙවියන් වැසි පාලනය කරන බැවින්", "කලා කටයුතු නිර්විඝ්නව නිම කිරීම සඳහා ගණ දෙවි ආශිර්වාදය පතයි."),
        q("වන්නමක 'කවිය' ගයන අතරතුර නැට්ටුවා අනුගමනය කරන පාද රටාව හඳුන්වන්නේ කුමන නමකින්ද?", "වන්නම් පා ගමන හෙවත් මන්දගාමී තාල පියවර", "වේගවත් කස්තිරම", "අවසන් බඹර පිනුම", "දිය කැපීමේ පියවර", "කවිය පැහැදිලිව ඇසීමට හා අභිනය දැක්වීමට මන්දගාමී පියවර යොදා ගනී."),
        q("උඩරට වන්නම් කවිවල 'එළිසමය' තබා රචනා කර තිබීමෙන් ලැබෙන ප්‍රයෝජනය කුමක්ද?", "මතක තබා ගැනීමේ පහසුව හා ගායනයේ සුමිහිරි රිද්මය", "කවිය දිගු වීම", "කවිය කියවීමට අපහසු වීම", "තාලය අමතක වීම", "පද හතරේ අවසාන අකුරු ගැළපීම නිසා ගායනය මිහිරි වේ."),
        q("උකුසා වන්නමේදී උකුස්සාගේ තියුණු ඇසින් ගොදුර නිරීක්ෂණය කරන ආකාරය පෙන්වන්නේ කුමන චලනයෙන්ද?", "හිස දෙපසට හරවා ඇස් තියුණු ලෙස යොමු කිරීමෙන් (දෘෂ්ටි භේද)", "දෑස් වසාගෙන කිසිදු චලනයක් නොදක්වා නිශ්චලව සිටීමෙන්", "ප්‍රේක්ෂකයාට පසුපස හැරී වේදිකාවේ පිටුපස බැලීමෙන්", "දණහිස් ඉහළට ඔසවාගෙන බිම වාඩි වී සිටීමෙන්", "දෘෂ්ටි චලනය හා ග්‍රීවා චලනය උකුසා වන්නමේ සජීවී බව වැඩි කරයි."),
        q("උඩරට නැටුමේදී 'තානම' ගැයීමට පෙර බෙරකරු විසින් ලබා දෙන ආරම්භක වාදනය හඳුන්වන්නේ කෙසේද?", "වට්ටම් තාලය හෙවත් අත් වට්ටම", "අවසන් අඩව්ව", "සීරුමාරුව", "දන්වැට පාලිය", "තානම කුමන ලයකින් ගැයිය යුතුද යන්න මෙම ආරම්භක බෙර පදයෙන් හඟවයි."),
        q("තුරඟා වන්නමේ තානම හඳුන්වන සාම්ප්‍රදායික ශබ්ද රටාව කුමක්ද?", "තන තන තම් දන තම් දන තනා", "තෙයි තත් තා", "ජෙග ජෙග දොං", "හුරේ තා නා", "වේගයෙන් දිව යන අශ්වයෙකුගේ කුර හඬට සමාන රිද්මයක් තුරඟා තානමේ ගැබ්වේ."),
        q("වන්නමක 'කස්තිරම' අවසන් කිරීමේදී යෙදෙන 'තීර්මානය' කී වරක් වාදනය කෙරේද?", "තුන් වරක් (ත්‍රිත්ව ආකාරයෙන්)", "එක් වරක් පමණි", "දහ වරක්", "විසි වරක්", "පෙරදිග නර්තන හා සංගීත සම්ප්‍රදාය අනුව තීර්මානය තෙවරක් ගොස් 'සම' ස්ථානයේ නතර වේ."),
        q("උඩරට දහඅට වන්නම්වල 'අසදිස' වන්නමේ ප්‍රධාන තේමාව ලෙස සැලකෙන්නේ කුමක්ද?", "අසමසම ගුණ ඇති බුදුරජාණන් වහන්සේගේ උතුම් චරිතය", "සිංහයාගේ දඩයම", "නාගයාගේ ගමන", "මොනරාගේ පිල් කලඹ", "'අසදිස' යනු කිසිවෙකුටත් සම කළ නොහැකි යන අර්ථයෙන් බුදුගුණ වර්ණනා කරයි."),
        q("උඩරට වන්නම් අතරින් 'රාජ්‍ය පාලකයාගේ උදාරත්වය' වර්ණනා කෙරෙන වන්නම කුමක්ද?", "උදාර වන්නම", "කිරලා වන්නම", "මුසලඩි වන්නම", "උරඟා වන්නම", "රජුගේ ඇමති මණ්ඩලය, පෙරහැර හා තේජස උදාර වන්නමේ කවියෙන් විස්තර වේ."),
        q("දහඅට වන්නම් අතුරින් 'වෛරෝඩි' වන්නම බොහෝ විට නිරූපණය කරන්නේ කුමන භාවමය ගුණයද?", "දිව්‍යමය අලංකාරය හා අද්භූත රසය", "වන සතුන්ගේ දඩයම", "ගොවි බිම් අස්වැන්න", "ධීවර ජීවිතය", "වෛරෝඩි මැණික් හා දේව ලෝක වර්ණනා මෙහි අන්තර්ගත වේ."),
        q("වන්නමක් ඉදිරිපත් කිරීමේදී ගායකයා කවිය ගයන අතරතුර නැට්ටුවා අඩව් නොනටා සෞම්‍යව රඟන්නේ ඇයි?", "කවියේ පද හා අර්ථය ප්‍රේක්ෂකයාට පැහැදිලිව ඇසීමට ඉඩ දීමට", "නැට්ටුවාට පාද චලන අමතක වූ නිසා", "බෙරය බිඳී ඇති නිසා", "වේදිකාව ඉතා කුඩා නිසා", "ගායනයට බාධා නොවන සේ කවි පදයට අනුරූප අභිනය පෙන්වීම සම්ප්‍රදායයි."),
        q("උඩරට වන්නම් කවිවල බහුලව භාවිත වන 'සමුද්‍රඝෝෂ' හෝ 'මත්තේභ' වැනි විරිත්වලින් ලැබෙන ගුණය කුමක්ද?", "ගායනයේදී ඉබේම තාලමය රිද්මයක් හා ලාලිත්‍යයක් ගොඩනැගීම", "කවියේ අකුරු කියවීමට බැරි වීම", "වචන කෙටි වී නැති වීම", "තාලම්පට අනවශ්‍ය වීම", "සිංහල ඡන්දස් ශාස්ත්‍රයේ මාත්‍රා විරිත් වන්නම්වලට මනා සංගීතමය රිද්මයක් දෙයි."),
        q("උඩරට වන්නම් සම්ප්‍රදායේදී 'ඊරඩි' වන්නමෙන් නිරූපණය කරන ප්‍රධාන ක්‍රියාදාමය කුමක්ද?", "යුද ශිල්පය හා ඊතල විදීමේ වික්‍රමය", "මල් නෙළීම", "ජලය ගෙන ඒම", "වී පෙළීම", "ඊතල හැඩැති වේගවත් ගමන් හා අංග චලන ඊරඩි වන්නමේ විශේෂත්වයකි."),
        q("පැරණි වන්නම් කවි පොත්වල දැක්වෙන පරිදි 'වන්නම් 18' හැරුණු විට වෙනත් වන්නම් රචනා වී තිබේද?", "ඔව්, පසුකාලීන කවීන් විසින් 18 ට අමතරව තවත් අමතර වන්නම් කිහිපයක් රචනා කර ඇත", "නැත, ලෝකයේ කිසිදු වෙනත් කවියක් ලියැවී නැත", "වන්නම් ඇත්තේ දෙකක් පමණි", "සියලු වන්නම් විනාශ වී ඇත", "සම්මත 18 ට අමතරව සමනල, බෝසත්, කන්දස්වාමි වැනි අමතර වන්නම්ද හමුවේ."),
        q("වන්නමක 'තාලය' හඳුනා ගැනීමට ශිෂ්‍යයා භාවිත කළ යුතු ප්‍රධාන මිනුම් ඒකකය කුමක්ද?", "මාත්‍රා ගණන සහ තිත් සංඛ්‍යාව", "මීටර් සහ සෙන්ටිමීටර්", "කිලෝග්‍රෑම් සහ ග්‍රෑම්", "ලීටර් සහ මිලිලීටර්", "එක් තාල ආවර්තයක ඇති මාත්‍රා ප්‍රමාණය අනුව වන්නමේ තාලය නිර්ණය කෙරේ."),
        q("මයුරා වන්නමේ කවි තුළින් වර්ණනා කෙරෙන කඳ කුමරුගේ වාහනය වන මොනරාගේ විශේෂ අංගය කුමක්ද?", "දිදුලන නීල වර්ණ ගෙල හා දහස් ගණන් ඇස් ඇති පිල් කලඹ", "දිගු ශක්තිමත් ඇත් දළ යුගලය හා කඳ", "පුළුල්ව ඉදිරියට දිගු වූ සොඬවැල", "ගාම්භීර ලෙස විහිදුණු රන් සිංහ කේසරය", "මොනරාගේ රූප ස්වභාවය අතිශයින් අලංකාර කාව්‍යෝක්තිවලින් වර්ණනා වේ."),
        q("සිංහරාජ වන්නම නැටීමේදී නැට්ටුවා 'පපුව ඉදිරියට පුම්බා පළල් මණ්ඩියෙන්' ගමන් කරන්නේ ඇයි?", "සිංහයාගේ ගාම්භීරත්වය හා අභීත බව නිරූපණය කිරීමට", "බිය වී හැංගීමට", "විඩාවෙන් වැටීමට", "හාවෙකු මෙන් පැනීමට", "වන්නමේ තේමාවට අනුව ශරීර අභිනය හැඩගැසීම ඉතා වැදගත් වේ."),
        q("හනුමා වන්නමේ 'කවිය' ගයන විට ගායකයා කටහඬ හසුරුවන විලාසය කෙබඳු විය යුතුද?", "කඩිසර හා විනෝදකාමී රිද්මයකින් යුක්තව", "අඬමින් හා වැළපෙමින්", "කිසිදු ස්වර වෙනසක් නැතිව", "නිදිමත හඬකින්", "වඳුරු රංගනයේ උද්යෝගය ප්‍රේක්ෂකයාට දැනෙන සේ ගායනය විය යුතුය."),
        q("උඩරට වන්නම්වල 'අඩව්ව' නටන අවස්ථාවේදී 'තාලම්පට' වාදනය සිදු වන්නේ කෙසේද?", "වේගවත් පදවලට අනුරූපව ලය රැකගෙන ස්ථිරව වාදනය වේ", "තාලම්පට බිම තබා ඉවත් වේ", "ගායකයා නින්දට යයි", "බෙර වාදනය නවතී", "තාලම්පට අඩව්වේ වේගවත් පියවරවලදී පවා තාලය නොබිඳී තබා ගනී."),
        q("උරඟා වන්නමේදී ගැටබෙරයෙන් වාදනය වන පද රටා බොහෝ විට පෙන්වන්නේ කුමන ස්වභාවයක්ද?", "සර්පයාගේ ලිස්සන සුළු හා ක්ෂණික පහරදීමේ රිද්මය", "ඇතාගේ බර පියවර හඬ", "අශ්වයාගේ කුර හඬ", "වැස්සේ හඬ", "බෙර පද මඟින් අදාළ සත්වයාගේ ස්වභාවය ශබ්දයෙන් මවා පෙන්වයි."),
        q("උඩරට නැටුමේදී 'වන්නම් 18' ඉගෙනීමෙන් ශිෂ්‍යයාට ලැබෙන සාහිත්‍යමය ප්‍රතිලාභය කුමක්ද?", "පැරණි සිංහල කාව්‍ය ව්‍යවහාරය, වෘත්ත හා සාහිත්‍ය රසය හඳුනාගැනීම", "පහතරට කෝලම් වෙස්මුහුණු කැපීමේ ශිල්පය ප්‍රගුණ කිරීම", "බටහිර ඔපෙරා හා සිම්ෆනි සංගීත සම්ප්‍රදාය හැදෑරීම", "නූතන වේදිකා ආලෝකකරණ තාක්ෂණය ඉගෙන ගැනීම", "වන්නම් කවි සිංහල කාව්‍ය සම්ප්‍රදායේ වටිනා කොටසකි."),
        q("නෛයඩි වන්නමේ 'කස්තිරම' අනෙකුත් වන්නම්වලින් වෙනස් වන හෝ කැපී පෙනෙන ලක්ෂණය කුමක්ද?", "සියුම් මණ්ඩි මාරුවීම් හා නාග පෙන ආකාරයේ අත් චලන", "කිසිදු පාද චලනයක් නොතිබීම", "වෙස් තට්ටුව ගලවා තැබීම", "පුටුවක වාඩි වී නැටීම", "නාගයාගේ නැමෙනසුළු හා තේජාන්විත ස්වභාවය මෙහි නිරූපණය වේ."),
        q("කිරලා වන්නමේ තානම හා කවිය අයත් වන්නේ කුමන ලය මට්ටමකටද?", "මධ්‍ය ලය හා කඩිසර වේගවත් රිද්මයට", "අතිශය මන්දගාමී ලයට", "නිශ්චල විරාමයට", "තාල රහිත රිද්මයට", "කුඩා පක්ෂියාගේ ක්‍රියාශීලී බව පෙන්වීමට මධ්‍ය හා ද්‍රුත ලය යොදයි."),
        q("ගජගා වන්නමේදී ඇතා දිය කෙළියේ යෙදෙන ආකාරය දැක්වීම සඳහා නැට්ටුවා කරන අභිනය කුමක්ද?", "දිය ඉසින ආකාරයෙන් දෙඅත් හිස මතින් ඉදිරියට විසි කිරීම", "මුහුණ රෙද්දකින් වසා ගැනීම", "දණ ගසා අඬන ලෙස පෙන්වීම", "වේදිකාවෙන් පිටතට ඇවිදීම", "කවියේ එන දිය කෙළි විස්තරයට අනුව සුන්දර අභිනයන් ඉදිරිපත් කෙරේ."),
        q("උඩරට වන්නම්වලදී 'මහ තුන් තිත' යනුවෙන් හඳුන්වන තාල ව්‍යුහය තුළ ඇති ලක්ෂණය කුමක්ද?", "දිගු මාත්‍රා ප්‍රමාණයක් සහිතව තිත් තුනකින් ආවර්තය නිම වීම", "එක් මාත්‍රාවකින් අවසන් වීම", "මාත්‍රා සියයක් තිබීම", "කිසිදු තිතක් නොමැති වීම", "මහ තාලයන්හිදී ගාම්භීර හා මන්දගාමී ව්‍යුහයක් ගොඩනැගේ."),
        q("උඩරට දහඅට වන්නම්වලින් 'අසදිස' වන්නමේ කවි ගායනා කරන විට පවත්වා ගත යුතු මානසික භාවය කුමක්ද?", "ශාන්ත හා භක්තිමත් ගෞරවය", "කෝපය හා රෞද්‍ර බව", "උපහාසය හා සිනහව", "භය හා තැතිගැන්ම", "බුදුගුණ වර්ණනා කරන බැවින් අතිශය ශාන්ත හා ගෞරවනීය බවක් තිබිය යුතුය."),
        q("සුරපති වන්නමේ කතා පුවත තුළ සඳහන් වන ප්‍රධාන දේව චරිත දෙක මොනවාද?", "ශිව (ඊශ්වර) දෙවියන් හා උමා දේවිය හෝ ශක්‍ර දෙවියන්", "රාම සහ රාවණා පමණි", "විජය සහ කුවේණි පමණි", "ගුරුහාමි සහ සොකරි", "දිව්‍යමය කතා පුවතක් කවි මගින් සුරපති වන්නමේ රසවත්ව ගායනා කෙරේ."),
        q("වන්නම් නර්තනයේදී 'තානම' සහ 'කවිය' අතර වෙනස කුමක්ද?", "තානම අර්ථ රහිත නාද අකුරු වන අතර කවිය අර්ථවත් පද්‍ය රචනයකි", "තානම ඉංග්‍රීසි බසින්ද කවිය පාලි බසින්ද වේ", "දෙකම අර්ථ රහිත ශබ්ද පමණි", "දෙකම නැටුම් පමණක් වන අතර ගායනා නොකරයි", "තානම රිද්මය මවන අතර කවිය වන්නමේ කථා වස්තුව හා වර්ණනාව කියයි."),
        q("තුරඟා වන්නම නැටීමේදී නැට්ටුවා 'දෑත් පපුව ඉදිරියේ තබා ඉහළ පහළ ගෙනයන්නේ' කුමක් සංකේතවත් කිරීමටද?", "අශ්වයාගේ රැහැන් පට අල්ලාගෙන අසු මෙහෙයවීම", "කළයක් හිස මත තබා ගැනීම", "කුල්ලකින් වී පෙළීම", "හාවෙකු අල්ලා ගැනීම", "අසරුවෙකු අසු මෙහෙයවන විලාසය මෙම අභිනයෙන් ප්‍රකට වේ."),
        q("උඩරට නැටුමේදී 'වන්නම් 18' ආරක්ෂා වී තිබෙන පැරණි ලිඛිත මූලාශ්‍ර හඳුන්වන්නේ කුමන නමකින්ද?", "වන්නම් පුස්කොළ පොත් හා පාරම්පරික කවි සංග්‍රහ", "නූතන චිත්‍රපට දෙබස් පිටපත්", "බටහිර සම්භාව්‍ය ස්වර ප්‍රස්තාර පොත්", "විදේශීය ගමන් විස්තර සංග්‍රහ", "පැරණි පුස්කොළ පොත් හා පරම්පරාගත ගුරු පොත් මගින් වන්නම් පද සුරැකිණි."),
        q("උඩරට නැටුමේ 'වන්නම්' නැටීම සඳහා සුදුසුම සාම්ප්‍රදායික ඇඳුම කුමක්ද?", "උඩරට වෙස් ඇඳුම හෝ නෛයන්ඩි ඇඳුම", "පහතරට සන්නි මුහුණ", "කෝලම් රජ ඇඳුම", "බටහිර ටයි කෝට් ඇඳුම", "උත්සව හා වේදිකා අවස්ථා අනුව උඩරට සම්ප්‍රදායික ඇඳුමෙන් වන්නම් නටනු ලැබේ."),
        q("උඩරට වන්නම්වලදී 'මණ්ඩිය පැද්දීම' යන්නෙන් අදහස් කරන ශාරීරික චලනය කුමක්ද?", "මණ්ඩි ඉරියව්වෙන් සිට දණහිස් ලයට අනුව මෘදුව පහළ ඉහළ නැමීම", "දෙපා සෘජුව කෙළින් තබා ඉහළ අහසට උඩ පැනීම", "පාද නොසොල්වා හිස පමණක් දෙපසට කරකැවීම", "වේදිකාව මැද බිම නිශ්චලව ඉඳගෙන සිටීම", "මණ්ඩිය පැද්දීම නිසා නැටුමට ජීවමාන රිද්මයක් හා ලාලිත්‍යයක් එක් වේ."),
        q("ගජගා වන්නමේදී ඇතාගේ ගමනට අනුරූපව 'හොඬවැල වැනීම' පෙන්වන අවස්ථාවේ අනෙක් අත තබන්නේ කොතැනද?", "ඉණ අසල හෝ සමතුලිතව කලවා අසල රඳවා ගනී", "හිස මුදුනේ බැඳ තබයි", "සාක්කුවේ දමා ගනී", "බෙර වාදකයාගේ උරහිසේ තබයි", "දෑත් අතර සමතුලිතතාව රැකීම නර්තන අලංකාරයට අත්‍යවශ්‍ය වේ."),
        q("උඩරට වන්නම්වල 'වෛරෝඩි' වන්නමේ තානම ගැයීමේදී පවතින රිද්ම රටාව කුමක්ද?", "තාලයට අනුව උස් පහත් වන සුමට හා ආකර්ෂණීය නාද රටාව", "කිසිදු නාද වෙනසක් නැති කෙඳිරීම", "අපහැදිලි ශබ්ද", "තනි වචනයක් පමණි", "වෛරෝඩි වන්නමේ සෞන්දර්යය එහි ගායනයෙන්ම ඉස්මතු වේ."),
        q("දහඅට වන්නම් අතරින් 'කුදිරඩි' වන්නම සඳහා භාවිත කළ හැකි වෙනත් සමාන නාමය කුමක්ද?", "ඉරඩි වන්නම", "ගජගා වන්නම", "අසදිස වන්නම", "කිරලා වන්නම", "අසුන් පැදීම හා රණ ශූරයෙකුගේ ගමන මෙම වන්නමේ විවිධ ප්‍රාදේශීය ව්‍යවහාර ලෙස හමුවේ."),
        q("උඩරට වන්නම් පද රචනා කර ඇති කාව්‍ය සම්ප්‍රදායේ විශේෂ ලක්ෂණයක් වන්නේ කුමක්ද?", "සෑම පේළියකම වචන ගැළපීම්වලින් බෙර පද රිද්මය මතු වීම", "කෙටි ඉංග්‍රීසි වචන යෙදීම", "එළිසමය සම්පූර්ණයෙන් බැහැර කිරීම", "පද්‍ය නොව ගද්‍ය වීම", "වන්නම් කවියේ මාත්‍රා ශබ්දයම ගැටබෙර තාලයට සෘජුවම ගැළපේ."),
        q("උඩරට වන්නමක 'තානම' ගැයීමෙන් පසු 'මුල් පදය' හෙවත් 'තාල පදය' වයන විට නැට්ටුවා ගමන් කරන්නේ කෙසේද?", "වේදිකාවේ ඉදිරියට හා පැත්තට මූලික වට පියවරවලින් ගමන් කරයි", "එක්වරම වේදිකාවෙන් පිටව යයි", "බිම වැතිරේ", "වෙස් තට්ටුව ගලවයි", "කවියට පෙර වේදිකා අවකාශය අත්පත් කර ගැනීම මෙම ගමනින් සිදු වේ."),
        q("උඩරට වන්නම්වලදී 'පංචතූර්ය' වාදනයෙන් ප්‍රධාන වශයෙන්ම වන්නම සමඟ බැඳී සිටින භාණ්ඩ දෙක කුමක්ද?", "ගැටබෙරය සහ තාලම්පට", "හොරණෑව සහ දවුල", "තම්මැට්ටම සහ හක්ගෙඩිය", "රබාන සහ උඩැක්කිය", "ගැටබෙරයේ හා තාලම්පටේ සුසංයෝගයෙන් වන්නම් නැටුම පෝෂණය වේ."),
        q("නෛයඩි වන්නමේ 'කවි' කියන විට සිදුහත් කුමරුන් සමඟ එහි වර්ණනා වන අනෙක් ශිල්පය කුමක්ද?", "ධනු ශිල්පය හෙවත් දුනු ශිල්පය", "නාවික ශිල්පය", "මූර්ති ශිල්පය", "කෘෂිකර්මය", "යශෝධරා කුමරිය සරණ පාවා ගැනීමට පෙර දුනු ශිල්ප දැක්වීම මෙම කවියේ ඇතුළත් වේ."),
        q("සිංහරාජ වන්නමේ 'කස්තිරම' හා 'අඩව්ව' නටන විට නැට්ටුවාගේ උරහිස් හා පපුව කෙසේ තබා ගත යුතුද?", "පළල්ව හා ප්‍රතාපවත් ලෙස ඉදිරියට විහිදා", "ඇතුළට හකුළුවාගෙන", "පහළට නවාගෙන", "එක් පැත්තකට ඇල කරගෙන", "සිංහයාගේ තේජස හා නොබියවන ස්වභාවය උඩුකයේ ඉරියව්වෙන් පෙනේ."),
        q("හනුමා වන්නම නැටීමේදී නැට්ටුවා 'අතින් පාදයේ ඇඟිලි හෝ දණහිස ස්පර්ශ කරන' ඉරියව්වෙන් පෙන්වන්නේ කුමක්ද?", "වඳුරෙකු කසමින් පනින හාස්‍යජනක අනුකරණය", "භාවනාවට වාඩි වීම", "දෙවියන්ට මල් පූජා කිරීම", "අශ්වයා පිට නැගීම", "සත්ව චර්යාවන් අතිශය සියුම්ව නිරූපණය කිරීම හනුමා වන්නමේ විශේෂත්වයකි."),
        q("මයුරා වන්නමේදී මොනරා 'වැස්ස දැක සතුටු වන' අවස්ථාව නිරූපණය කිරීමේදී නැට්ටුවා කුමක් කරයිද?", "අහස දෙස බලා ප්‍රීතිමත් දෘෂ්ටියක් හා ලලිත පිල් චලන දක්වයි", "බියෙන් පසුපස හැරී වේදිකාවෙන් පලා යයි", "හිස පහළ හෙළා ශෝකී ලෙස හඬා වැළපෙයි", "සංගීතය මැද නැටුම සම්පූර්ණයෙන් නවතා සිටී", "වැසි සමයේ මොනරාගේ නැටුම කවිවලින් මනාව වර්ණනා කර ඇත."),
        q("කිරලා වන්නමේ 'කිරලා' පක්ෂියාගේ සුවිශේෂී හැසිරීමක් ලෙස වන්නමෙන් දැක්වෙන්නේ කුමක්ද?", "අහසට පියාඹා හඬ නඟා පොළොවට බැස ඇවිදීම", "ජලය යට පිහිනීම", "ගල් ගුහාවක නිදා ගැනීම", "ගස් මත කූඩු තැනීම", "කිරලාගේ හඬ හා බිම දිව යන පියවර නර්තනයට නඟා ඇත."),
        q("උරඟා වන්නමේදී නාගයා 'පෙනය පුප්පා පහර දෙන' මොහොත බෙර පදයෙන් හඳුන්වන්නේ කෙසේද?", "ක්ෂණික තියුණු කස්තිරම් පහරකින්", "මන්දගාමී නිහඬතාවකින්", "සීනු හඬකින්", "දිගු වට්ටමකින්", "සර්පයාගේ ක්ෂණික චලනය බෙරයේ වේගවත් පදයකින් සංකේතවත් වේ."),
        q("උඩරට දහඅට වන්නම් අතර 'පද' සහ 'මාත්‍රා' මතක තබා ගැනීමට ශිෂ්‍යයෙකු මුලින්ම කළ යුත්තේ කුමක්ද?", "වන්නමේ කවිය හා තාලම්පට තිතට අනුව වාචිකව පද පුහුණු වීම", "නර්තන පින්තූර ඇතුළත් පොතක් නිහඬව කියවීම පමණක්", "වෙස් තට්ටුව හිසේ පැළඳගෙන පාඩම් කියවීම පමණක්", "වේදිකා තිර රෙදිවල පින්තූර රටා ඇඳ තැබීම", "හඬ නඟා පද කීම මඟින් ශරීරය තුළ රිද්මය මුල් බැස ගනී."),
        q("අසදිස වන්නම අනෙක් වන්නම්වලින් වෙනස් වී උසස් ශාස්ත්‍රීය අගයක් ගැනීමට ප්‍රධාන හේතුව කුමක්ද?", "බුද්ධ චරිතයේ අසමසම ගුණ මහිමය ගැඹුරු ඡන්දස් අලංකාරයෙන් වර්ණනා කිරීම", "වනාන්තරයේ සිටින වඳුරන්ගේ චපල චර්යා ගැන කතා කිරීම", "හාස්‍ය රසය උපදවන විකට දෙබස් කවියට ඇතුළත් වී තිබීම", "වචන දෙකකින් පමණක් යුත් ඉතා කෙටි ගීතයක් වීම", "ශාස්ත්‍රීය සාහිත්‍ය හා සංගීතයේ සුසංයෝගය අසදිස වන්නමේ ඉහළින්ම පවතී."),
        q("සුරපති වන්නමේදී 'සුරපති' යනු ශක්‍රයා වුවත් එම කවිවල ප්‍රධාන වශයෙන්ම කියැවෙන කතා පුවත කාගේද?", "ඊශ්වර දෙවියන් හා උමා දේවියගේ පුවත", "විජය කුමරුගේ පුවත", "දුටුගැමුණු රජුගේ පුවත", "ජසයාගේ පුවත", "මෙම වන්නම ඊශ්වර වන්නම ලෙසද ඇතැම් පැරණි පොත්වල හඳුන්වා ඇත."),
        q("ගණපති වන්නමේ කවිය අවසානයේ නටන 'කස්තිරම' තුළ දැකිය හැකි ප්‍රධාන රිද්ම ස්වභාවය කුමක්ද?", "ප්‍රසන්න, සුමට හා උත්සවශ්‍රීයෙන් යුත් පාද තැබීම", "රෞද්‍ර කෝපයෙන් හා යුද සටනින් යුත් පොරබැදීම", "අධික ශෝකී හැඬීම හා විලාප නැගීමෙන් නැටීම", "සමබරතාව ගිලිහී වේදිකාව මත ඇද වැටීම", "ගණ දෙවි ආශිර්වාදය නිසා සතුටුදායක හා සංයමයකින් යුත් චලන මෙහි යෙදේ."),
        q("උදාර වන්නමේ කවි ගයන විට ගායකයා කටහඬ පවත්වා ගත යුත්තේ කුමන ස්වභාවයකින්ද?", "ගාම්භීර, තේජාන්විත හා පැහැදිලි හඬකින්", "බියගුළු හා කෙඳිරිලි හඬකින්", "සිනාසෙමින්", "අඬමින්", "රාජකීය උදාරත්වය හඬින්ද ප්‍රේක්ෂකයාට දැනිය යුතුය."),
        q("උඩරට වන්නම්වලදී 'අත් මාරු' කියා දීමේදී ආධුනිකයාට වැදගත් වන අත් හරවා ගැනීමේ රීතිය කුමක්ද?", "මැණික් කටුව ලිහිල්ව හා වෘත්තාකාරව කැරකැවීම", "වැළමිට තදින් ඇලවා තැබීම", "ඇඟිලි සියල්ල මිට මෙළවීම", "දෑත් පිටුපසින් තැබීම", "අත්වල සුමට හැසිරවීම නැටුමේ භාවය හා ලාලිත්‍යය රකී."),
        q("උඩරට වන්නම් 18 න් 'වෛරෝඩි' වන්නමේදී වර්ණනා කෙරෙන 'වෛරෝඩි' යනු කුමක්ද?", "වෛදූර්ය මැණික හා දිව්‍යමය දීප්තිය", "වන සතෙක්", "කෘෂි උපකරණයක්", "යුද ආයුධයක්", "වටිනා මැණිකක පැහැය හා දිව්‍ය ශෝභාව මෙම වන්නමේ තේමාවට මුල් වේ."),
        q("උඩරට වන්නම්වල 'සත්ව වන්නම්' නැටීමේදී ශිල්පියා සත්වයෙකු අනුකරණය කරන ආකාරය කෙබඳු විය යුතුද?", "නාට්‍යමය හා කලාත්මක සංකේතවත් කිරීමක් ලෙස (විකෘති නොකර)", "සැබෑ සතෙකු මෙන් හතරගාතයෙන් දිවීමෙන්", "ශබ්ද නඟා කෑගැසීමෙන්", "ඇඳුම් ඉරා ගැනීමෙන්", "සොබාදහමේ සතෙකුගේ ගුණාංග උසස් කලාත්මක මට්ටමකට ඔසවා තැබීම වන්නමේ විශේෂත්වයයි."),
        q("වන්නමක 'මාත්‍රා' කොටස් ගණනය කිරීමේදී 'තකුඳ තකුඳ' යනු කුමන බෙර පදයක්ද?", "සිව් මාත්‍රා (චතුරස්‍ර) ලය ගමන් පදයක්", "හය මාත්‍රා පදයක්", "නව මාත්‍රා පදයක්", "එක් මාත්‍රා පදයක්", "මූලික පාද තැබීම්වලදී තාලය තබා ගැනීමට මෙම බෙර පද කියැවේ."),
        q("උඩරට වන්නම් ඉදිරිපත් කිරීමේදී 'නැට්ටුවා' සහ 'ගැටබෙර වාදකයා' අතර ඇතිවන අවසාන ගිවිසුම කුමක්ද?", "සම ස්ථානයේදී එකට තීර්මානය නිමා කිරීම", "වෙන වෙනම වේදිකාවෙන් පිටවීම", "නැටුම මැද බෙරය නැවැත්වීම", "තාලම්පට විසි කිරීම", "වාදකයාගේ අවසන් පහර හා නැට්ටුවාගේ අවසන් සිටීම එකම තත්පරයේ සිදුවිය යුතුය."),
        q("උඩරට දහඅට වන්නම් 'වේදිකා කලාවට' පැමිණීමට පෙර ගැයූ හා නැටූ ප්‍රධාන ස්ථානය කුමක්ද?", "මහනුවර රජ මාලිගයේ කවිකාර මඩුව සහ දේවාල උත්සව", "කොළඹ වරාය", "යාපනය කොටුව", "ත්‍රිකුණාමලය නාවික තොට", "රාජ සභාවේ ගීත කලාවක් ලෙස පෝෂණය වී පසුව නැටුම් එක් විය."),
        q("තුරඟා වන්නමේ 'අඩව්ව' තුළ දක්නට ලැබෙන විශේෂ පියවරක් වන්නේ කුමක්ද?", "එක් පාදයකින් තවත් පාදයකට මාරු වෙමින් අසුගේ ගමන සිහිගන්වන පැනුම්", "දෙදණහිස් බිම තබා ඉතා සෙමින් ඉදිරියට ඇවිදීම", "සම්පූර්ණ වටයක් පුරා බිම වැතිරී නිශ්චලව සිටීම", "හිස බිමට නමා දෙඅත් හිස මත තබාගෙන සිටීම", "වන්නමේ චරිතය අඩව්වේදී පවා ජීවමාන කිරීම ශිල්පියාගේ දක්ෂතාවයි."),
        q("මයුරා වන්නමේ 'කස්තිරම' අවසන් කිරීමෙන් පසු 'සීරුමාරුව' නටන විට නැට්ටුවා පවත්වා ගන්නා ඉරියව්ව කුමක්ද?", "සුළු මණ්ඩි ඉරියව්වෙන් සමබරව සිට දෑත් දෙපසට විහිදා සැලීම", "පසුපස හැරී ඉඳගැනීම", "කෙළින් සිටගෙන ඇස් පියා ගැනීම", "බෙර වාදකයා ළඟට දිව යාම", "සීරුමාරුව ඊළඟ වේගවත් කොටසට සූදානම් වීමේ සමබර පියවරකි."),
        q("ගජගා වන්නමේ තාලම්පට වැයෙන ආකාරය හා මාත්‍රා බෙදීම කෙබඳු වේද?", "සම කාල පරතරයකින් 'තිත් තා' හඬ දෙමින් ගැඹුරු ගමන් ලය රැකීම", "ඉතා වේගයෙන් කැඩී කැඩී වැයීම", "කිසිදු තාලම්පටක් නොවැයීම", "බටහිර ඩ්‍රම් තාලයට වැයීම", "ඇතාගේ මන්දගාමී පියවරවලට තාලම්පට නාදය මැනවින් සහාය වේ."),
        q("උඩරට නැටුමේදී 'වන්නමක සෑම කවියක්ම එකම තාලයෙන් ගැයිය යුතුද'?", "ඔව්, එක් වන්නමකට නියමිත මූලික තාලය හා විරිත කවි පුරාම ආරක්ෂා වේ", "නැත, සෑම පදයකදීම වෙනත් වන්නමක තාලයට මාරු වේ", "පළමු කවියට පමණක් තාලයක් ඇත", "කවි ගැයීම තහනම්ය", "ඒකාබද්ධ තාල ව්‍යුහය වන්නමේ සංගීතමය අනන්‍යතාව රකී."),
        q("උකුසා වන්නම නැටීමේදී නැට්ටුවා 'දෑත් පියාපත් සේ ඉහළට විහිදා වටයක් කැරකීම' සංකේතවත් කරන්නේ කුමක්ද?", "උකුස්සා අහසේ රවුම් ගසමින් ගොදුරු සෙවීම", "මොනරා පිල් විදහීම", "සර්පයා බිම දිගේ යාම", "ඇතා දිය බීම", "ගුවනේ පියාසර රටා වේදිකාව මත චලනවලින් මැවේ."),
        q("හනුමා වන්නමේදී ශිල්පියා පෙන්නුම් කරන 'අංග ලක්ෂණ' මගින් ප්‍රේක්ෂකයා තුළ ඇති වන ප්‍රධාන හැඟීම කුමක්ද?", "විනෝදය, සිනහව සහ කඩිසර බව පිළිබඳ රසය", "දැඩි ශෝකය හා හැඬීම", "මරණ බිය", "රෞද්‍ර කෝපය", "හාස්‍ය රසය වන්නම් 18 අතර ප්‍රබලව හනුමා වන්නමෙන් ඉදිරිපත් වේ."),
        q("සිංහරාජ වන්නමේ තේමාව තුළ සිංහයා 'කඳු මුදුනක සිට ගර්ජනා කරන' අවස්ථාවේ නැට්ටුවා කෙසේ හැසිරෙයිද?", "හිස ඉහළට ඔසවා, පපුව පුම්බා, දැඩි තේජාන්විත දෘෂ්ටියක් හෙළයි", "බියෙන් වේදිකාව මත වැතිරී ශෝකීව හඬා වැළපෙයි", "දෙඅත්වලින් මුහුණ වසාගෙන ඉවතට හැරී සිටී", "පසුපසට පැන වේදිකා තිරය පිටුපස සැඟවී සිටී", "වීර රසය ප්‍රබලව ඉස්මතු කිරීම සඳහා ශරීරය පුළුල්ව තබා ගනී."),
        q("මුසලඩි වන්නමේ කවිය ගයන විට හාවා බිය වී දුවන ආකාරය පෙන්වන්නේ කුමන චලනයකින්ද?", "වේගවත් කෙටි පියවරවලින් හා දිශාව මාරු කරමින්", "ඉතා සෙමින් ගාටමින්", "එකම තැන නිදා ගනිමින්", "බෙරය මත වාඩි වීමෙන්", "හාවාගේ අනාරක්ෂිත හා කඩිසර ස්වභාවය ඉන් පිළිබිඹු වේ."),
        q("කිරලා වන්නමේදී කිරලා කුරුල්ලා තම කූඩුව හා බිත්තර ආරක්ෂා කිරීමට නඟන හඬ කාව්‍යමය ලෙස යොදා ඇත්තේ කොතැනද?", "කවියේ වචන හා තානමේ නාද අනුකරණය තුළ", "බෙර වාදකයා කෑගැසීමෙන්", "ප්‍රේක්ෂකයන්ගේ අත්පුඩියෙන්", "සීනු නාද කිරීමෙන්", "පක්ෂියාගේ නාදයට සමාන ශබ්ද රිද්මයක් තානම තුළ ගැබ්ව තිබේ."),
        q("නෛයඩි වන්නමේ නාමය සහිත 'නෛයන්ඩි' ඇඳුම් කට්ටලය අතර ඇති සම්බන්ධය කුමක්ද?", "නාමයන් සමාන වුවත් නෛයඩි යනු වන්නමක් වන අතර නෛයන්ඩි යනු පූජා ඇඳුම් කට්ටලයයි", "මේ දෙකම උඩරට හා පහතරට සම්ප්‍රදායේ බෙර වර්ග දෙකකි", "නෛයඩි යනු පහතරට කෝලම් රංගනයේ පළඳින වෙස්මුහුණකි", "මේ දෙකම පහතරට සන්නි යාගයේ නැටුම් පෙළපාලි දෙකකි", "පද දෙකේ වෙනස නිවැරදිව හඳුනා ගැනීම නර්තන ශිෂ්‍යයාට වැදගත් වේ."),
        q("උරඟා වන්නම නැටීමේදී ශිල්පියාගේ 'මැණික් කටුව හා ඇඟිලි' සකස් විය යුත්තේ කුමන හැඩයකටද?", "නාග පෙනයක් මෙන් ඇඟිලි ලං කර නමා සර්පශීර්ෂ හෝ පතක හැඩයට", "තදින් මිට මොළවාගෙන", "ඇඟිලි පිටුපසට නවාගෙන", "අත් දෙක ඉණේ තබාගෙන", "සර්ප ශීර්ෂය හා ඇදී යාම සංකේතවත් කිරීමට මෙම අත් ඉරියව්ව යෙදේ."),
        q("ඊරඩි වන්නමේ 'ඊරඩි' යන වචනයෙන් බොහෝ විට සිහිගන්වන්නේ කුමන ශිල්පීය සංකල්පයක්ද?", "ඊතලය මෙන් වේගවත් දෙපියවර හා යුද සටන් ගමන", "මල් නෙළන මෘදු ගමන", "නිදා ගැනීම", "දිය නෑම", "රණශූර රිද්මය ඊරඩි වන්නමේ සෑම අංගයකම දිස්වේ."),
        q("වෛරෝඩි වන්නමේදී නැට්ටුවා 'දෙව් ලොව' සුන්දරත්වය අභිනයෙන් දක්වන්නේ කුමන ආකාරයෙන්ද?", "ඉහළ අහස දෙස බලා අලංකාර අලපද්ම හා පතක මුද්‍රා පෙන්වීමෙන්", "බිම කුණු අතුගාන අයුරු අත් මුද්‍රාවෙන් පෙන්වීමෙන්", "බර ඉසිලීමේ ශක්තිමත් ඉරියව් අභිනයෙන් පෙන්වීමෙන්", "රංගනය අවසන් නොකර වේදිකාවෙන් පිටතට බැස යාමෙන්", "දිව්‍යමය පරිසරය සංකේතවත් කිරීමට ප්‍රසන්න මුද්‍රා හා ඉහළ දෘෂ්ටි යොදයි."),
        q("ගණපති වන්නම නර්තනයේදී ගණ දෙවියන්ගේ 'හොඬවැල' හා 'උදරය' දැක්වීම සඳහා යොදන අභිනය කුමක්ද?", "අත නාසය ඉදිරියෙන් වක්‍ර කර පෙන්වා ගජ මුහුණ නිරූපණය කිරීම", "දඟකාර වඳුරු මුහුණක් මුහුණු අභිනයෙන් පෙන්වීම", "වේගවත් අශ්ව හිසක හැඩය හස්ත මුද්‍රාවෙන් පෙන්වීම", "කුරුළු හොටක හැඩය ඇඟිලි තුඩුවලින් පෙන්වීම", "ගණ දෙවි රූප ලක්ෂණ කාව්‍යානුකූලව අභිනයෙන් පෙන්වයි."),
        q("සුරපති වන්නමේදී 'මල්සරා' අළු බවට පත්වූ පුවත කවිවල සඳහන් වේ නම් එමඟින් දැනෙන රසය කුමක්ද?", "අද්භූත හා කරුණා රසය", "හුදු හාස්‍යය පමණි", "යුද බිය පමණි", "පිළිකුල් භීභත්ස රසය", "දේව පුරාවෘත්තයේ නාටකීය සිදුවීම් රසවත්ව ගායනා කෙරේ."),
        q("උදාර වන්නමේ 'කවි' ගායනා කිරීමේදී පවත්වා ගත යුතු 'තාල සංයමය' කුමක්ද?", "නොසැලෙන මධ්‍ය ලය හා ගෞරවනීය රිද්මය රැකීම", "හැකිතාක් ඉක්මනින් කියවා අවසන් කිරීම", "තාලය නොතකා හිතුමතේ ගැයීම", "අතරමගදී ගීතය වෙනස් කිරීම", "රාජ ප්‍රතාපය හා උදාර බව තාලයේ ස්ථාවරත්වයෙන් රැකේ."),
        q("අසදිස වන්නමේදී බුදුරජාණන් වහන්සේගේ 'දෙතිස් මහා පුරුෂ ලක්ෂණ' හෝ ගුණ වර්ණනා වන විට නැට්ටුවා දක්වන මුද්‍රාව කුමක්ද?", "අංජලී හස්තය හා පතක හස්තය වැනි ගෞරවනීය මුද්‍රා", "මුෂ්ටි හස්තයෙන් පහර දීම", "සූචි හස්තයෙන් තර්ජනය කිරීම", "වඳුරු අනුකරණය", "බුදුගුණ වන්දනාවට අතිශය ශාන්ත හා විනීත මුද්‍රා යොදා ගනී."),
        q("උඩරට දහඅට වන්නම්වල 'බෙර පද' අධ්‍යයනය කිරීමෙන් ශිෂ්‍යයාට ලැබෙන සංගීතමය දැනුම කුමක්ද?", "සිංහල තාල ශාස්ත්‍රය, මාත්‍රා බෙදීම හා ගැටබෙර අක්ෂර හැසිරවීම", "බටහිර පියානෝ ස්වර ප්‍රස්තාර", "විද්‍යුත් ගිටාර් සැකසුම්", "චිත්‍ර වර්ණ ගැන්වීම", "නර්තනය හා සංගීත රිද්මයේ බැඳීම පිළිබඳ ගැඹුරු අවබෝධයක් ලැබේ."),
        q("වන්නම් 18 අතර 'ඉතා කෙටි හා කඩිසර' ලක්ෂණ පෙන්වන වන්නම් දෙකකට උදාහරණ මොනවාද?", "මුසලඩි වන්නම සහ කිරලා වන්නම", "අසදිස වන්නම සහ ගජගා වන්නම", "උදාර වන්නම සහ සිංහරාජ වන්නම", "ගණපති වන්නම සහ සුරපති වන්නම", "කුඩා සතුන්ගේ චලන නිරූපණය කරන මෙම වන්නම් කඩිසර රිද්මයකින් යුක්තය."),
        q("උඩරට වන්නමක් වේදිකාවේ ඉදිරිපත් කරන විට 'සමූහ වන්නම්' රංගනයකදී තබන පොදු හැඩතලය කුමක්ද?", "සමාන්තර පේළි, වෘත්ත හෝ ත්‍රිකෝණාකාර විධිමත් රටා", "එකිනෙකාට පිටුපා හිඳගැනීම", "පොදියට තෙරපී සිටීම", "වේදිකාවෙන් පිටත සිටීම", "සමූහ වන්නම්වල අභිමානය දෘශ්‍යමාන රටාවන්ගෙන් තවදුරටත් වැඩි වේ."),
        q("උඩරට වන්නම්වල 'තානම් කවි' පොත්පත්වල ලේඛනගත වීමෙන් වත්මන් සිසුන්ට ලැබුණු ප්‍රධාන වාසිය කුමක්ද?", "පැරණි ගුරුකුලවල නිවැරදි පද හා කවි විකෘති නොවී ඉගෙන ගැනීමට හැකි වීම", "පැරණි වන්නම් කවි සියල්ල භාවිතයෙන් අමතක වීම", "වන්නම් සංඛ්‍යාව අඩු වී පාඨමාලා කෙටි වීම", "සාම්ප්‍රදායික ගැටබෙර වාදනය සම්පූර්ණයෙන් නතර වීම", "මුද්‍රිත ග්‍රන්ථ නිසා දිවයිනේ සෑම පාසලකටම සම්මත වන්නම් පද ලැබී ඇත."),
        q("වන්නම් නර්තනයේදී 'වෙස් ඇඳුම' පැළඳ ගැනීමට සුදුසුකම් ලැබූ ශිල්පියෙකු වන්නමක් නැටීමේදී පෙන්වන උසස්ම ගුණය කුමක්ද?", "තාල නිවැරදි බව, ශරීර පාලනය සහ සාම්ප්‍රදායික අභිමානය", "හිතුමතේ පැනීම", "වෙස් තට්ටුව පැත්තකට ඇල කිරීම", "බෙරකරුට පෙර අවසන් කිරීම", "වෙස් නැට්ටුවාගේ විනය හා කලා පරිණත බව වන්නමෙන් මැන බැලේ."),
        q("උඩරට නැටුමේදී 'ගජගා වන්නම' නැටීමෙන් පසු ප්‍රේක්ෂකයා තුළ ඉතිරි වන ප්‍රධාන සෞන්දර්ය හැඟීම කුමක්ද?", "ශාන්ත, ගාම්භීර හා අභිමානවත් කලාත්මක තෘප්තිය", "බිය සහ තැතිගැන්ම", "අධික කෝපය", "පිළිකුල", "මන්දගාමී හා ශාස්ත්‍රීය රිද්මය මනසට ගාම්භීර සුවයක් ගෙන එයි."),
        q("උඩරට වන්නම් සම්ප්‍රදාය පාසල් සිසුන් අතර ප්‍රචලිත කිරීමෙන් මෙරට සංස්කෘතියට සිදුවන ප්‍රධාන සේවය කුමක්ද?", "දේශීය ශාස්ත්‍රීය නර්තන උරුමය අනාගත පරපුරට අඛණ්ඩව සුරැකීම", "විදේශීය නැටුම් පමණක් වැළඳ ගැනීම", "සිංහල සාහිත්‍යය අත්හැරීම", "බෙර වාදනය නැවැත්වීම", "පාසල් අධ්‍යාපනය හරහා වන්නම් කලාව දිවයින පුරා ජීවමානව පවතී."),
        q("දහඅට වන්නම් අධ්‍යයනයේදී 'තානම, කවිය, කස්තිරම, සීරුමාරුව, අඩව්ව' යන පංච අංග එක්වීමෙන් ගොඩනැගෙන්නේ කුමක්ද?", "පරිපූර්ණ ශාස්ත්‍රීය උඩරට වන්නම් රංග ආකෘතියයි", "පහතරට සන්නි පෙළපාලියයි", "සබරගමු ගමන් පදයයි", "බටහිර බැලේ ප්‍රසංගයයි", "මෙම පියවර පහ වන්නමකට ආරම්භය, විකාශනය හා සමාප්තිය ලබා දෙයි.")
    )
}
